import os
import time
import requests


OPENAI_API_KEY = os.environ["OPENAI_API_KEY"]
OPENAI_BASE_URL = "https://api.openai.com/v1"
MODEL = "gpt-4o-transcribe"


def submit_batch_transcription(audio_file_path: str) -> str:
    headers = {"Authorization": f"Bearer {OPENAI_API_KEY}"}

    with open(audio_file_path, "rb") as f:
        files = {"file": (os.path.basename(audio_file_path), f, "application/octet-stream")}
        data = {"purpose": "batch"}
        upload_resp = requests.post(
            f"{OPENAI_BASE_URL}/files",
            headers=headers,
            files=files,
            data=data,
            timeout=300,
        )
    upload_resp.raise_for_status()
    input_file_id = upload_resp.json()["id"]

    batch_body = {
        "endpoint": "/v1/audio/transcriptions",
        "completion_window": "24h",
        "input_file_id": input_file_id,
        "metadata": {"job_type": "speech_to_text"},
    }
    batch_resp = requests.post(
        f"{OPENAI_BASE_URL}/batches",
        headers={**headers, "Content-Type": "application/json"},
        json=batch_body,
        timeout=60,
    )
    batch_resp.raise_for_status()
    return batch_resp.json()["id"]


def get_batch_status(batch_id: str) -> dict:
    resp = requests.get(
        f"{OPENAI_BASE_URL}/batches/{batch_id}",
        headers={"Authorization": f"Bearer {OPENAI_API_KEY}"},
        timeout=60,
    )
    resp.raise_for_status()
    return resp.json()


def wait_for_batch(batch_id: str, poll_interval_seconds: int = 10) -> dict:
    while True:
        status = get_batch_status(batch_id)
        if status["status"] in {"completed", "failed", "expired", "cancelled"}:
            return status
        time.sleep(poll_interval_seconds)


def download_batch_output(batch_id: str) -> str:
    status = get_batch_status(batch_id)
    output_file_id = status.get("output_file_id")
    if not output_file_id:
        raise RuntimeError(f"No output file available for batch {batch_id}; status={status.get('status')}")

    resp = requests.get(
        f"{OPENAI_BASE_URL}/files/{output_file_id}/content",
        headers={"Authorization": f"Bearer {OPENAI_API_KEY}"},
        timeout=300,
    )
    resp.raise_for_status()
    return resp.text


def submit_and_wait(audio_file_path: str) -> str:
    batch_id = submit_batch_transcription(audio_file_path)
    final_status = wait_for_batch(batch_id)
    if final_status["status"] != "completed":
        raise RuntimeError(f"Batch {batch_id} ended with status {final_status['status']}")
    return download_batch_output(batch_id)
